package orchestrator

import "time"

// Frontier job reasons (informational — carried on Job for the operator log).
const (
	reasonPilot  = "pilot"
	reasonNext   = "next-after-watched"
	reasonRepack = "repack"
)

// Episode is the ONE packaging-relevant projection of an item (the narrow
// input the policies judge). Packable folds the classification gate
// (stream.Classify == pack, or opt_in with the knob on — the caller's
// decision); Packaged means a playable build is already published (streams
// state partial or complete); CoolUntil is the pack_failed cooldown
// deadline (zero = never failed / cooldown elapsed).
type Episode struct {
	ItemID    string
	Packable  bool
	Packaged  bool
	CoolUntil time.Time
}

// Serial is one serial's episode list in CANONICAL ORDER — the exact order
// the episodes endpoint emits (QueryItemsBySeries: relative_path ordered,
// depth-1) — plus its library's streams-enabled gate. LibraryID is carried
// through to the returned Jobs so the caller can log/attribute enqueues.
type Serial struct {
	LibraryID      int64
	StreamsEnabled bool
	Episodes       []Episode
}

// FrontierIn is the frontier's input snapshot: every serial of every
// streams-gated library, the set of watched item ids (completion-aware —
// the caller judges the predicate where the documents are; this package
// never reads one), and the evaluation clock (injected — this package never
// reads a clock).
type FrontierIn struct {
	Serials []Serial
	Watched map[string]bool
	Now     time.Time
}

// Job is ONE enqueue decision: the item to package, its library (for
// attribution), and why the fronted picked it. The caller executes it via
// the enrich queue's pack seam.
type Job struct {
	ItemID    string
	LibraryID int64
	Reason    string
}

// Frontier decides the watch-driven packaging frontier (D-8; spec
// "Watch-driven packaging frontier"). Per serial, exactly ONE candidate is
// considered — the frontier position: the episode one past the LAST watched
// episode (canonical order), or the pilot (first episode) for a serial with
// no watch progress — and it is enqueued only when eligible (packable, not
// already packaged, outside its failure cooldown). A streams-disabled
// library is skipped at the gate; a never-pre-warmed movie library is
// absent from the input by construction (movies pack on play — OnPlay).
//
// It returns the eligible jobs AND the WORKING SET — the frontier-position
// item of every gated, not-fully-watched serial, whether or not a job was
// emitted for it this pass. The working set is the budget sweep's eviction
// pin: a position item that is packaged (or cooling) emits no job today but
// WILL be the frontier's next repack after any eviction — pinning only the
// job-emitting ticks is the evict→repack churn loop (the set empties exactly
// when fresh builds exist to protect). The result is deterministic: serials
// in input order, one job per serial at most, empty slice never nil.
func Frontier(in FrontierIn) ([]Job, map[string]bool) {
	jobs := make([]Job, 0)
	fronted := make(map[string]bool)
	for _, sr := range in.Serials {
		if !sr.StreamsEnabled || len(sr.Episodes) == 0 {
			continue // gate: disabled library (or empty serial) — nothing fronts
		}
		last := -1
		for i, ep := range sr.Episodes {
			if in.Watched[ep.ItemID] {
				last = i // canonical order: the LAST index wins
			}
		}
		if last == len(sr.Episodes)-1 {
			continue // the whole serial is watched — nothing is past the frontier
		}
		reason := reasonPilot
		if last >= 0 {
			reason = reasonNext
		}
		cand := sr.Episodes[last+1] // pilot (last<0) or K+1-after-watched
		fronted[cand.ItemID] = true // the working set: pinned whether or not eligible
		if !eligible(cand, in.Now) {
			continue
		}
		jobs = append(jobs, Job{ItemID: cand.ItemID, LibraryID: sr.LibraryID, Reason: reason})
	}
	return jobs, fronted
}

// OnPlay is the pack-on-play decision (D-8; the movie half of the frontier
// the sweep never fronts): a PLAYED item is enqueued exactly when it is
// eligible — packable, nothing published yet, outside its failure cooldown.
// The caller applies it to the played item's Episode projection; the same
// eligibility rule as the sweep (single source in this package).
func OnPlay(e Episode, now time.Time) bool {
	return eligible(e, now)
}

// IntegrityItem is ONE integrity-sweep fact (D4's policy half): the item id
// and whether its published build still validates (stream.ValidateBuild —
// the caller runs the check and hands down the verdict; this package never
// touches disk).
type IntegrityItem struct {
	ItemID  string
	Healthy bool
}

// Repacks is the integrity sweep's pure repack judge (D4): exactly the
// unhealthy items come back as repack jobs — healthy items never job, input
// order preserved, empty slice never nil. The caller's gates are the same as
// the frontier's: in-flight leases and pack_failed cooldowns are applied at
// the enqueue site, never here — the judge is the policy, the sweep is the
// composition (D4).
func Repacks(items []IntegrityItem) []Job {
	jobs := make([]Job, 0)
	for _, it := range items {
		if !it.Healthy {
			jobs = append(jobs, Job{ItemID: it.ItemID, Reason: reasonRepack})
		}
	}
	return jobs
}
